import sys,numpy as np,json
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();o=r.get_obs(video='none');q=np.array(o.meta['proprio']['now'][:7]);print('q',q,'tcp',o.meta['proprio']['now'][8:15]);
def mul(a,b):
 w,x,y,z=a;W,X,Y,Z=b
 return np.array([w*W-x*X-y*Y-z*Z,w*X+x*W+y*Z-z*Y,w*Y-x*Z+y*W+z*X,w*Z+x*Y-y*X+z*W])
qdown=o.meta['proprio']['now'][11:15];qdown=np.array(qdown);qyaw=mul([np.sqrt(.5),0,0,np.sqrt(.5)],qdown)
print('qdown',qdown,'qyaw',qyaw)
for name,pose in [('mug_pre',[.59,.07,.22,*qyaw]),('mug_grasp',[.59,.07,.065,*qyaw]),('bin_pre',[.53,.29,.23,*qyaw]),('bin_release',[.53,.29,.08,*qyaw]),('bowl_pre',[.39,-.21,.22,*qdown]),('bowl_grasp',[.39,-.21,.055,*qdown]),('bowl_binpre',[.53,.29,.24,*qdown])]:
 ans=r.ik({'tcp':pose},seed=q); print(name,ans.get('ok'),ans.get('q'),ans.get('error'))
